package cn.iocoder.yudao.module.platform.api.tenant;import cn.iocoder.yudao.module.platform.api.tenant.dto.packages.TenantPackageRespDTO;import cn.iocoder.yudao.module.platform.convert.tenant.TenantPackageConvert;import cn.iocoder.yudao.module.platform.service.tenant.TenantPackageService;import org.springframework.stereotype.Service;import javax.annotation.Resource;/** * 租户套餐API实现 * * @author zhusy * @since 2022/8/6 */@Servicepublic class TenantPackageApiImpl implements TenantPackageApi {    @Resource    private TenantPackageService tenantPackageService;    @Override    public TenantPackageRespDTO getTenantPackage(Long id) {        return TenantPackageConvert.INSTANCE.convertDTO(tenantPackageService.getTenantPackage(id));    }}